import React, { useEffect, useMemo, useRef, useState } from "react";
import { AccessibilityInfo, PanResponder, View, type ViewStyle } from "react-native";
import {
  BlurStyle,
  Canvas,
  Group,
  Picture,
  PointMode,
  Skia,
  StrokeCap,
  TileMode,
  vec,
  type SkCanvas,
  type SkPicture,
} from "@shopify/react-native-skia";
import { STEP_COUNT } from "./foldMath";
import { FOLD_H, FOLD_W, buildFrame, staticScene, type Item } from "./foldDesign";

export type OrigamiFoldProps = {
  /** Fold step to rest at, 0 (flat sheet) to 4 (finished). Change it to fold or unfold with an animation. */
  step?: number;
  /** Width in layout points; the sheet keeps its 340 x 420 proportions. */
  width?: number;
  slowMotion?: boolean;
  reducedMotion?: boolean;
  /** Called when the paper comes to rest on a fold step. */
  onStepChange?: (step: number) => void;
  /** Hook haptics here: 'grab', 'crease' (a fold lands, strength 0 to 1) and 'release'. */
  onFeedback?: (event: "grab" | "crease" | "release", strength?: number) => void;
  label?: string;
  style?: ViewStyle;
};

function safeDispose(o: unknown): void {
  const d = (o as { dispose?: () => void } | null | undefined)?.dispose;
  if (typeof d === "function") {
    try {
      d.call(o);
    } catch {
      /* some hosts free these on their own */
    }
  }
}

/** Paint a draw list with Skia. */
function paintItems(canvas: SkCanvas, items: Item[]) {
  const paint = Skia.Paint();
  paint.setAntiAlias(true);
  const blurs = new Map<number, ReturnType<typeof Skia.MaskFilter.MakeBlur>>();
  for (const it of items) {
    if (it.k === "poly") {
      const path = Skia.Path.Make();
      path.moveTo(it.pts[0], it.pts[1]);
      for (let i = 2; i < it.pts.length; i += 2) path.lineTo(it.pts[i], it.pts[i + 1]);
      path.close();
      paint.setShader(null);
      paint.setMaskFilter(null);
      paint.setColor(Skia.Color(it.color));
      let shader: ReturnType<typeof Skia.Shader.MakeLinearGradient> | null = null;
      if (it.grad) {
        shader = Skia.Shader.MakeLinearGradient(
          vec(it.grad.x0, it.grad.y0),
          vec(it.grad.x1, it.grad.y1),
          [Skia.Color(it.grad.c0), Skia.Color(it.grad.c1)],
          null,
          TileMode.Clamp,
        );
        paint.setShader(shader);
      }
      if (it.blur) {
        const key = Math.round(it.blur * 10);
        let f = blurs.get(key);
        if (!f) {
          f = Skia.MaskFilter.MakeBlur(BlurStyle.Normal, it.blur / 2, true);
          blurs.set(key, f);
        }
        paint.setMaskFilter(f);
      }
      paint.setAlphaf(it.alpha ?? 1);
      canvas.drawPath(path, paint);
      path.dispose?.();
      paint.setShader(null);
      safeDispose(shader);
    } else if (it.k === "dots") {
      paint.setShader(null);
      paint.setMaskFilter(null);
      paint.setColor(Skia.Color(it.color));
      paint.setAlphaf(it.alpha);
      paint.setStrokeWidth(it.size);
      paint.setStrokeCap(StrokeCap.Square);
      const pts = [];
      for (let i = 0; i < it.pts.length; i += 2) pts.push(vec(it.pts[i], it.pts[i + 1]));
      canvas.drawPoints(PointMode.Points, pts, paint);
    } else {
      paint.setShader(null);
      paint.setMaskFilter(null);
      paint.setColor(Skia.Color(it.color));
      paint.setAlphaf(it.alpha ?? 1);
      paint.setStrokeWidth(it.width);
      paint.setStrokeCap(StrokeCap.Round);
      canvas.drawLine(it.pts[0], it.pts[1], it.pts[2], it.pts[3], paint);
    }
  }
  blurs.forEach((f) => safeDispose(f));
  safeDispose(paint);
}


function record(items: Item[]): SkPicture {
  const rec = Skia.PictureRecorder();
  const canvas = rec.beginRecording(Skia.XYWHRect(0, 0, FOLD_W, FOLD_H));
  paintItems(canvas, items);
  return rec.finishRecordingAsPicture();
}

/** Pixels of finger travel for one full fold. */
const PX_PER_STEP = 150;

export function OrigamiFold({
  step = 0,
  width = FOLD_W,
  slowMotion = false,
  reducedMotion,
  onStepChange,
  onFeedback,
  label = "A sheet of origami paper on a desk. Drag sideways to fold it step by step, drag back to unfold",
  style,
}: OrigamiFoldProps) {
  const scale = width / FOLD_W;
  const height = FOLD_H * scale;
  const [systemReduce, setSystemReduce] = useState(false);
  const reduce = reducedMotion ?? systemReduce;
  const target0 = Math.max(0, Math.min(STEP_COUNT, Math.round(step)));
  const sim = useRef({ u: target0, v: 0, target: target0, held: false, lastStep: target0 });
  const latest = useRef({ slowMotion, reduce, onStepChange, onFeedback });
  latest.current = { slowMotion, reduce, onStepChange, onFeedback };
  const [back, setBack] = useState<SkPicture | null>(null);
  const [frame, setFrame] = useState<SkPicture | null>(null);
  const drag = useRef({ x: 0, t: 0, v: 0 });

  useEffect(() => {
    let alive = true;
    AccessibilityInfo.isReduceMotionEnabled()
      .then((v) => {
        if (alive) setSystemReduce(v);
      })
      .catch(() => {});
    const sub = AccessibilityInfo.addEventListener("reduceMotionChanged", setSystemReduce);
    return () => {
      alive = false;
      sub.remove();
    };
  }, []);

  useEffect(() => {
    const pic = record(staticScene().back);
    setBack(pic);
    return () => {
      setTimeout(() => safeDispose(pic), 1500);
    };
  }, []);

  // A new step prop sends the paper there.
  useEffect(() => {
    const s = sim.current;
    if (!s.held) s.target = Math.max(0, Math.min(STEP_COUNT, Math.round(step)));
  }, [step]);

  useEffect(() => {
    let alive = true;
    let last = 0;
    let prev: SkPicture | null = null;
    let lastU = -1;
    const retired: unknown[] = [];
    const loop = (now: number) => {
      if (!alive) return;
      const s = sim.current;
      const dt = last ? Math.min(0.05, (now - last) / 1000) : 1 / 60;
      last = now;
      if (!s.held) {
        if (latest.current.reduce) {
          s.u = s.target;
          s.v = 0;
        } else {
          // a lightly under-damped spring: the paper settles with a small, soft overshoot
          const k = 70;
          const c = 2 * Math.sqrt(k) * 0.8;
          const h = dt * (latest.current.slowMotion ? 0.25 : 1);
          const n = Math.max(1, Math.ceil(h / 0.004));
          for (let i = 0; i < n; i++) {
            const a = k * (s.target - s.u) - c * s.v;
            s.v += (a * h) / n;
            s.u += (s.v * h) / n;
          }
          s.u = Math.max(0, Math.min(STEP_COUNT, s.u));
          if (Math.abs(s.target - s.u) < 0.0008 && Math.abs(s.v) < 0.01) {
            s.u = s.target;
            s.v = 0;
          }
        }
        const nearest = Math.round(s.u);
        if (Math.abs(s.u - nearest) < 0.0001 && nearest !== s.lastStep) {
          latest.current.onFeedback?.("crease", Math.min(1, 0.4 + Math.abs(s.v) * 0.2));
          s.lastStep = nearest;
          latest.current.onStepChange?.(nearest);
        }
      }
      if (Math.abs(s.u - lastU) > 1e-5 || !prev) {
        lastU = s.u;
        const pic = record(buildFrame(s.u));
        setFrame(pic);
        if (prev) retired.push(prev);
        while (retired.length > 8) safeDispose(retired.shift());
        prev = pic;
      }
      requestAnimationFrame(loop);
    };
    const raf = requestAnimationFrame(loop);
    return () => {
      alive = false;
      cancelAnimationFrame(raf);
      const rest = [...retired, prev];
      setTimeout(() => rest.forEach(safeDispose), 1500);
    };
  }, []);

  const pan = useMemo(
    () =>
      PanResponder.create({
        onStartShouldSetPanResponder: () => !latest.current.reduce,
        onPanResponderGrant: (evt) => {
          const s = sim.current;
          s.held = true;
          s.v = 0;
          drag.current = { x: evt.nativeEvent.locationX / scale, t: Date.now(), v: 0 };
          latest.current.onFeedback?.("grab", 0.3);
        },
        onPanResponderMove: (evt) => {
          const s = sim.current;
          const d = drag.current;
          const x = evt.nativeEvent.locationX / scale;
          const now = Date.now();
          const du = (x - d.x) / PX_PER_STEP;
          s.u = Math.max(0, Math.min(STEP_COUNT, s.u + du));
          const dtm = Math.max(1, now - d.t) / 1000;
          d.v = d.v * 0.6 + (du / dtm) * 0.4;
          d.x = x;
          d.t = now;
        },
        onPanResponderRelease: () => {
          const s = sim.current;
          s.held = false;
          const v = drag.current.v;
          // a flick carries on to the next step; a slow release settles on the nearest
          s.target = Math.max(0, Math.min(STEP_COUNT, Math.round(s.u + Math.max(-1, Math.min(1, v * 0.22)))));
          s.v = Math.max(-6, Math.min(6, v));
          latest.current.onFeedback?.("release", Math.min(1, Math.abs(v) / 4));
        },
        onPanResponderTerminate: () => {
          const s = sim.current;
          s.held = false;
          s.target = Math.max(0, Math.min(STEP_COUNT, Math.round(s.u)));
        },
        onPanResponderTerminationRequest: () => false,
      }),
    [scale],
  );

  return (
    <View
      style={[{ width, height, borderRadius: 18, overflow: "hidden", backgroundColor: "#1d1d21" }, style]}
      accessibilityLabel={label}
      accessibilityRole="image"
      {...pan.panHandlers}
    >
      <Canvas pointerEvents="none" style={{ width, height }}>
        <Group transform={[{ scale }]}>
          {back ? <Picture picture={back} /> : null}
          {frame ? <Picture picture={frame} /> : null}
        </Group>
      </Canvas>
    </View>
  );
}

/* Origami fold geometry. Pure TypeScript, no dependencies.

   The sheet is a list of flat convex facets stacked in layers. Each fold step
   is a crease line; every facet the crease crosses is cut in two and the side
   behind the crease swings over it by pi, ending reflected, flipped and on top
   of the pile. Posing the sheet at a fractional step rotates just those
   facets about the crease, so the same data folds forward and unfolds back. */

export type P2 = [number, number];
export type V3 = [number, number, number];

export type Facet = { pts: P2[]; layer: number; flipped: boolean };
export type CutFacet = Facet & { move: boolean; layerAfter: number };

/** Fold the side where n.p < d over onto the side where n.p > d. */
export type Crease = { nx: number; ny: number; d: number };

const R = Math.SQRT1_2;
/* Unit sheet, half-size 1. Four folds: corner to corner, the tip down to the
   middle of the long edge, the left half over, then the bottom edge up. */
export const CREASES: Crease[] = [
  { nx: R, ny: R, d: 0 },
  { nx: -R, ny: -R, d: -R },
  { nx: 1, ny: 0, d: 0 },
  { nx: 0, ny: 1, d: -0.42 },
];
export const STEP_NAMES = ["Fold corner to corner", "Tuck the tip down", "Fold the left half over", "Fold the base up"];
/** Layer spacing in sheet units, so stacked paper never z-fights. */
export const THICK = 0.012;
/** How far a freely swinging flap lags then leads its crease (radians). */
const BEND = 0.2;

function area(pts: P2[]): number {
  let a = 0;
  for (let i = 0; i < pts.length; i++) {
    const [x0, y0] = pts[i];
    const [x1, y1] = pts[(i + 1) % pts.length];
    a += x0 * y1 - x1 * y0;
  }
  return a / 2;
}

/** Sutherland-Hodgman clip of a convex polygon to f(p) >= 0 (sign = 1) or f(p) <= 0 (sign = -1). */
function clip(pts: P2[], c: Crease, sign: 1 | -1): P2[] {
  const f = (p: P2) => sign * (c.nx * p[0] + c.ny * p[1] - c.d);
  const out: P2[] = [];
  for (let i = 0; i < pts.length; i++) {
    const a = pts[i];
    const b = pts[(i + 1) % pts.length];
    const fa = f(a);
    const fb = f(b);
    if (fa >= -1e-9) out.push(a);
    if ((fa > 1e-9 && fb < -1e-9) || (fa < -1e-9 && fb > 1e-9)) {
      const t = fa / (fa - fb);
      out.push([a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t]);
    }
  }
  return out;
}

function reflect(p: P2, c: Crease): P2 {
  const s = c.nx * p[0] + c.ny * p[1] - c.d;
  return [p[0] - 2 * s * c.nx, p[1] - 2 * s * c.ny];
}

export type FoldModel = {
  /** states[i] is the flat sheet before step i; states[CREASES.length] is the finished fold. */
  states: Facet[][];
  /** cuts[i] is states[i] split along crease i, with the moving pieces flagged. */
  cuts: CutFacet[][];
};

export function buildModel(): FoldModel {
  const states: Facet[][] = [[{ pts: [[-1, -1], [1, -1], [1, 1], [-1, 1]], layer: 0, flipped: false }]];
  const cuts: CutFacet[][] = [];
  for (const c of CREASES) {
    const cur = states[states.length - 1];
    const stay: Facet[] = [];
    const move: Facet[] = [];
    for (const f of cur) {
      const a = clip(f.pts, c, 1);
      const b = clip(f.pts, c, -1);
      if (a.length >= 3 && Math.abs(area(a)) > 1e-6) stay.push({ pts: a, layer: f.layer, flipped: f.flipped });
      if (b.length >= 3 && Math.abs(area(b)) > 1e-6) move.push({ pts: b, layer: f.layer, flipped: f.flipped });
    }
    const top = Math.max(0, ...stay.map((f) => f.layer), ...move.map((f) => f.layer));
    const maxMove = Math.max(0, ...move.map((f) => f.layer));
    const moved: Facet[] = move.map((f) => ({
      // reflecting reverses the winding, so reverse the points to keep them counter-clockwise
      pts: f.pts.map((p) => reflect(p, c)).reverse(),
      layer: top + 1 + (maxMove - f.layer),
      flipped: !f.flipped,
    }));
    const cut: CutFacet[] = [
      ...stay.map((f) => ({ ...f, move: false, layerAfter: f.layer })),
      ...move.map((f, i) => ({ ...f, move: true, layerAfter: moved[i].layer })),
    ];
    cuts.push(cut);
    states.push([...stay, ...moved]);
  }
  return { states, cuts };
}

export const MODEL = buildModel();
export const STEP_COUNT = CREASES.length;

export const ease = (t: number) => (t <= 0 ? 0 : t >= 1 ? 1 : t * t * t * (t * (t * 6 - 15) + 10));

export type PosedFacet = {
  /** Vertices in sheet space: x right, y away from the viewer, z up. */
  pts: V3[];
  /** Unit normal of the side that shows colour A, per vertex. */
  normals: V3[];
  flipped: boolean;
  moving: boolean;
  layer: number;
  /** Rotation angle of the moving flap, 0 to pi; 0 for pieces that stay put. */
  phi: number;
  /** Distance of each vertex from the crease, for shading ramps. */
  dist: number[];
  /** Height of the pile the flap lands on (sheet units). */
  floor: number;
};

/** Pose the sheet at fold progress u in [0, STEP_COUNT]. */
export function pose(u: number): PosedFacet[] {
  const uu = Math.max(0, Math.min(STEP_COUNT, u));
  const s = Math.min(STEP_COUNT - 1, Math.floor(uu));
  const e = uu - s;
  const c = CREASES[s];
  const phi = Math.PI * ease(e);
  const cp = Math.cos(phi);
  const sp = Math.sin(phi);
  const out: PosedFacet[] = [];
  for (const f of MODEL.cuts[s]) {
    const zb = f.layer * THICK;
    const za = f.layerAfter * THICK;
    const sz = f.flipped ? -1 : 1;
    if (!f.move) {
      out.push({
        pts: f.pts.map((p) => [p[0], p[1], zb] as V3),
        normals: f.pts.map(() => [0, 0, sz] as V3),
        flipped: f.flipped,
        moving: false,
        layer: f.layer,
        phi: 0,
        dist: f.pts.map((p) => Math.abs(c.nx * p[0] + c.ny * p[1] - c.d)),
        floor: zb,
      });
      continue;
    }
    const pts: V3[] = [];
    const normals: V3[] = [];
    const dist: number[] = [];
    for (const p of f.pts) {
      const uAlong = c.nx * p[0] + c.ny * p[1] - c.d; // negative on the moving side
      const dd = Math.abs(uAlong);
      const pv = phi - BEND * Math.sin(2 * phi) * Math.min(1, dd / 1.3);
      const cv = Math.cos(pv);
      const sv = Math.sin(pv);
      const lift = zb + (za - zb) * (phi / Math.PI);
      // base point on the crease, then swing about it
      const bx = p[0] - uAlong * c.nx;
      const by = p[1] - uAlong * c.ny;
      pts.push([bx + uAlong * cv * c.nx, by + uAlong * cv * c.ny, lift - uAlong * sv]);
      normals.push([sz * sv * c.nx, sz * sv * c.ny, sz * cv]);
      dist.push(dd);
    }
    out.push({ pts, normals, flipped: f.flipped, moving: true, layer: f.layer, phi, dist, floor: 0 });
  }
  void cp;
  void sp;
  // the flap lands on whatever stays: record the pile height under it
  const stayTop = Math.max(0, ...out.filter((f) => !f.moving).map((f) => f.floor));
  for (const f of out) if (f.moving) f.floor = stayTop;
  return out;
}

export const facetArea = (f: Facet) => Math.abs(area(f.pts));

/* Camera, lighting and the draw list for Origami Fold. Pure TypeScript: the
   same list is painted by the Skia component and by the web Canvas2D preview. */
import { MODEL, STEP_COUNT, ease, pose, type PosedFacet, type V3 } from "./foldMath";

export const FOLD_W = 340;
export const FOLD_H = 420;
/** Half the sheet edge in world units. */
const S = 3.4;

export type Item =
  | { k: "poly"; pts: number[]; color: string; alpha?: number; blur?: number; grad?: { x0: number; y0: number; x1: number; y1: number; c0: string; c1: string } }
  | { k: "dots"; pts: number[]; color: string; size: number; alpha: number }
  | { k: "line"; pts: number[]; color: string; width: number; alpha?: number };

/* ---------- camera: sheet x right, y away, z up -> world [x, z, -y] ---------- */
const EYE: V3 = [0, 13.5, 8.4];
const TARGET: V3 = [0, 0, -0.2];
const FOCAL = 520;
const CX = FOLD_W / 2;
const CY = FOLD_H * 0.5;

const sub = (a: V3, b: V3): V3 => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const dot = (a: V3, b: V3) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const cross = (a: V3, b: V3): V3 => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
const unit = (a: V3): V3 => {
  const l = Math.hypot(a[0], a[1], a[2]) || 1;
  return [a[0] / l, a[1] / l, a[2] / l];
};
const FWD = unit(sub(TARGET, EYE));
const RIGHT = unit(cross(FWD, [0, 1, 0]));
const UPV = cross(RIGHT, FWD);
const TO_CAM = unit(sub(EYE, [0, 0, 0])); // world space

/* The camera follows the folded shape: it recentres and zooms as the sheet shrinks. */
const VIEW = { cx: 0, cy: 0, zoom: 1 };
function setView(u: number) {
  const uu = Math.max(0, Math.min(STEP_COUNT, u));
  const i = Math.min(STEP_COUNT - 1, Math.floor(uu));
  const t = ease(uu - i);
  const box = (k: number) => {
    let x0 = 9, x1 = -9, y0 = 9, y1 = -9;
    for (const f of MODEL.states[k]) for (const p of f.pts) { x0 = Math.min(x0, p[0]); x1 = Math.max(x1, p[0]); y0 = Math.min(y0, p[1]); y1 = Math.max(y1, p[1]); }
    return { cx: (x0 + x1) / 2, cy: (y0 + y1) / 2, e: Math.max(x1 - x0, y1 - y0) / 2 };
  };
  const a = box(i);
  const b = box(i + 1);
  VIEW.cx = a.cx + (b.cx - a.cx) * t;
  VIEW.cy = a.cy + (b.cy - a.cy) * t;
  VIEW.zoom = Math.min(1.5, 1 / (a.e + (b.e - a.e) * t));
}
const world = (p: V3): V3 => [(p[0] - VIEW.cx) * VIEW.zoom * S, p[2] * VIEW.zoom * S, -(p[1] - VIEW.cy) * VIEW.zoom * S];
function proj(w: V3): [number, number, number] {
  const d = sub(w, EYE);
  const z = dot(d, FWD);
  const s = FOCAL / z;
  return [CX + dot(d, RIGHT) * s, CY - dot(d, UPV) * s, z];
}
const screen = (p: V3) => proj(world(p));

/* ---------- light ---------- */
// Light direction in sheet space (towards the light): from the front-left, high.
const LIGHT: V3 = unit([-0.45, -0.5, 1]);
// The same direction in world space for normals
const LIGHT_W: V3 = [LIGHT[0], LIGHT[2], -LIGHT[1]];
const FRONT_COL: [number, number, number] = [226, 66, 44]; // vermilion
const BACK_COL: [number, number, number] = [238, 231, 214]; // cream

const clamp = (v: number) => Math.max(0, Math.min(255, Math.round(v)));
const rgb = (c: [number, number, number], k: number, add = 0) => `rgb(${clamp(c[0] * k + add)},${clamp(c[1] * k + add)},${clamp(c[2] * k + add)})`;

/* Paper is matte with a faint sheen. `n` is the unit normal (sheet space) of the
   colour-A side; whichever side faces the camera is the one we see. */
function shade(n: V3, floor: number, depth: number): { col: string; side: "A" | "B" } {
  const nw: V3 = [n[0], n[2], -n[1]];
  const facing = dot(nw, TO_CAM) >= 0;
  const sn: V3 = facing ? nw : [-nw[0], -nw[1], -nw[2]];
  const diff = Math.max(0, dot(sn, LIGHT_W));
  const h = unit([LIGHT_W[0] + TO_CAM[0], LIGHT_W[1] + TO_CAM[1], LIGHT_W[2] + TO_CAM[2]]);
  const spec = Math.pow(Math.max(0, dot(sn, h)), 22) * 0.1;
  // light that has to reach down into a pile is a little dimmer
  const occl = 1 - Math.min(0.2, depth * 0.9) * (1 - Math.min(1, floor * 20));
  const k = (0.5 + 0.62 * diff) * (0.96 + 0.04 * occl);
  const base = facing ? FRONT_COL : BACK_COL;
  return { col: rgb(base, k, spec * 255), side: facing ? "A" : "B" };
}

/* Project the sheet onto the table along the light, for the cast shadow. */
function castPts(f: PosedFacet, lift: number): number[] {
  const out: number[] = [];
  for (const v of f.pts) {
    const z = Math.max(0, v[2] - lift);
    const p: V3 = [v[0] + (LIGHT[0] / LIGHT[2]) * -z, v[1] + (LIGHT[1] / LIGHT[2]) * -z, lift];
    const s = screen(p);
    out.push(s[0], s[1]);
  }
  return out;
}

/** Everything that never changes: the desk, its light pool and grain. */
export function staticScene(): { back: Item[] } {
  const back: Item[] = [];
  back.push({ k: "poly", pts: [0, 0, FOLD_W, 0, FOLD_W, FOLD_H, 0, FOLD_H], color: "#2a2a2e", grad: { x0: 0, y0: 0, x1: 0, y1: FOLD_H, c0: "#34343a", c1: "#1d1d21" } });
  // soft pool of light under the lamp
  const ring = (rx: number, ry: number, a: number, blur: number) => {
    const pts: number[] = [];
    for (let i = 0; i < 28; i++) {
      const t = (i / 28) * Math.PI * 2;
      pts.push(CX - 22 + Math.cos(t) * rx, CY + 8 + Math.sin(t) * ry);
    }
    back.push({ k: "poly", pts, color: "#fff1d6", alpha: a, blur });
  };
  ring(230, 210, 0.1, 70);
  ring(170, 150, 0.1, 50);
  ring(110, 100, 0.09, 36);
  // fine desk grain
  let seed = 1234567;
  const rnd = () => ((seed = (seed * 1664525 + 1013904223) >>> 0) / 4294967296);
  const pts: number[] = [];
  for (let i = 0; i < 340; i++) pts.push(rnd() * FOLD_W, rnd() * FOLD_H);
  back.push({ k: "dots", pts, color: "#ffffff", size: 1, alpha: 0.045 });
  const dark: number[] = [];
  for (let i = 0; i < 260; i++) dark.push(rnd() * FOLD_W, rnd() * FOLD_H);
  back.push({ k: "dots", pts: dark, color: "#000000", size: 1, alpha: 0.12 });
  return { back };
}

const dir2 = (a: number[], i: number, j: number) => [a[j] - a[i], a[j + 1] - a[i + 1]];

/** One frame of the folded sheet at fold progress u. */
export function buildFrame(u: number): Item[] {
  setView(u);
  const facets = pose(u);
  const items: Item[] = [];
  // Cast shadow on the desk: a wide soft one and a tight contact one.
  for (const f of facets) {
    if (f.pts.length < 3) continue;
    const high = Math.max(...f.pts.map((v) => v[2]));
    items.push({ k: "poly", pts: castPts(f, 0), color: "#000000", alpha: Math.max(0.1, 0.34 - high * 0.12), blur: 12 + high * 20 });
  }
  for (const f of facets) {
    if (f.pts.length < 3 || f.moving) continue;
    items.push({ k: "poly", pts: castPts(f, 0), color: "#000000", alpha: 0.26, blur: 3 });
  }
  // Painter's order: farther from the camera first.
  const order = facets
    .map((f) => {
      const c = f.pts.reduce((a, v) => [a[0] + v[0] / f.pts.length, a[1] + v[1] / f.pts.length, a[2] + v[2] / f.pts.length] as V3, [0, 0, 0] as V3);
      return { f, depth: screen(c)[2] - c[2] * 0.0 + 0 };
    })
    .sort((a, b) => b.depth - a.depth);
  // Piles read by height, so when two facets sit near the same depth, lower layers come first.
  order.sort((a, b) => {
    const za = a.f.pts.reduce((m, v) => m + v[2], 0) / a.f.pts.length;
    const zb = b.f.pts.reduce((m, v) => m + v[2], 0) / b.f.pts.length;
    if (Math.abs(a.depth - b.depth) < 0.35) return za - zb;
    return b.depth - a.depth;
  });
  for (const { f } of order) {
    if (f.pts.length < 3) continue;
    const sp: number[] = [];
    for (const v of f.pts) {
      const s = screen(v);
      sp.push(s[0], s[1]);
    }
    if (f.moving) {
      // the flap shades the paper it swings over
      const high = Math.max(...f.pts.map((v) => v[2]));
      const lift = f.floor + 0.004;
      items.push({ k: "poly", pts: castPts(f, lift), color: "#3a0f06", alpha: Math.min(0.32, 0.08 + high * 0.2) * Math.min(1, Math.sin(f.phi) * 3 + 0.2), blur: 6 + high * 10 });
    }
    // vertex colours -> one gradient from the crease side to the far side
    const cols = f.pts.map((v, i) => shade(f.normals[i], f.moving ? 0 : v[2], f.dist[i]));
    const cen = f.pts.reduce((a, v) => [a[0] + v[0] / f.pts.length, a[1] + v[1] / f.pts.length], [0, 0]);
    const fall = 1.05 - 0.07 * Math.min(1.6, Math.hypot(cen[0] + 0.5, cen[1] - 0.2));
    let lo = 0;
    let hi = 0;
    f.dist.forEach((d, i) => {
      if (d < f.dist[lo]) lo = i;
      if (d > f.dist[hi]) hi = i;
    });
    // when the visible side changes across the facet, keep the dominant one flat
    const mid = shade(f.normals[0], f.moving ? 0 : f.pts[0][2], f.dist[0]);
    const flat = !f.moving || cols.some((c) => c.side !== cols[0].side) || hi === lo;
    const item: Item = { k: "poly", pts: sp, color: flat ? mid.col : cols[lo].col };
    if (flat) {
      // a faint sheen across a flat piece keeps big areas of paper from looking printed
      let l = 0, r = 0;
      for (let i = 0; i < f.pts.length; i++) { if (sp[i * 2] < sp[l * 2]) l = i; if (sp[i * 2] > sp[r * 2]) r = i; }
      const m = mid.col.match(/\d+/g)!.map(Number);
      const tone = (k: number) => `rgb(${clamp(m[0] * k)},${clamp(m[1] * k)},${clamp(m[2] * k)})`;
      item.grad = { x0: sp[l * 2], y0: sp[l * 2 + 1], x1: sp[r * 2], y1: sp[r * 2 + 1], c0: tone(fall * 0.97), c1: tone(fall * 1.03) };
    }
    if (!flat) item.grad = { x0: sp[lo * 2], y0: sp[lo * 2 + 1], x1: sp[hi * 2], y1: sp[hi * 2 + 1], c0: cols[lo].col, c1: cols[hi].col };
    items.push(item);
    // creases and paper edge
    for (let i = 0; i < f.pts.length; i++) {
      const j = (i + 1) % f.pts.length;
      // the crease being folded right now only shows once the paper starts to bend
      const live = f.dist[i] < 1e-6 && f.dist[j] < 1e-6;
      items.push({ k: "line", pts: [sp[i * 2], sp[i * 2 + 1], sp[j * 2], sp[j * 2 + 1]], color: "#2b0a04", width: 0.7, alpha: 0.28 * (live ? Math.min(1, f.phi * 4) : 1) });
    }
    // a light edge on the lit lip of a lifted flap sells the paper thickness
    if (f.moving && Math.sin(f.phi) > 0.05) {
      const a = f.dist.map((d, i) => ({ d, i })).sort((p, q) => p.d - q.d).slice(0, 2);
      if (a.length === 2 && a[1].d < 1e-6) {
        items.push({ k: "line", pts: [sp[a[0].i * 2], sp[a[0].i * 2 + 1], sp[a[1].i * 2], sp[a[1].i * 2 + 1]], color: "#fff4e6", width: 1, alpha: 0.35 });
      }
    }
  }
  void dir2;
  return items;
}

import React, { useState } from "react";
import { Pressable, Text, View } from "react-native";
import { OrigamiFold } from "./OrigamiFold";
import { STEP_COUNT } from "./foldMath";

const NAMES = ["Flat sheet", "Corner to corner", "Tip tucked down", "Left half over", "Base folded up"];

export default function Example({
  onFeedback,
}: {
  onFeedback?: (event: "grab" | "crease" | "release", strength?: number) => void;
}) {
  const [slow, setSlow] = useState(false);
  const [reduce, setReduce] = useState(false);
  const [target, setTarget] = useState(0);
  const [at, setAt] = useState(0);
  const chip = (on: boolean) => ({
    paddingVertical: 9, paddingHorizontal: 13, borderRadius: 24, borderWidth: 1,
    backgroundColor: on ? "#315843" : "#eeeade", borderColor: on ? "#315843" : "#c7caba",
  });
  return (
    <View style={{ alignItems: "center", gap: 10, paddingVertical: 14 }}>
      <OrigamiFold step={target} slowMotion={slow} reducedMotion={reduce} onStepChange={setAt} onFeedback={onFeedback} />
      <Text accessibilityLiveRegion="polite" style={{ fontSize: 15, color: "#1f3a2a", fontFamily: "Geist-Regular", minHeight: 20 }}>
        Step {at} of {STEP_COUNT}: {NAMES[at]}
      </Text>
      <View style={{ flexDirection: "row", gap: 8, flexWrap: "wrap", justifyContent: "center" }}>
        <Pressable accessibilityRole="button" accessibilityState={{ disabled: target <= 0 }} onPress={() => setTarget((t) => Math.max(0, t - 1))} style={chip(false)}>
          <Text style={{ fontSize: 12, color: "#315843", fontFamily: "Geist-Regular" }}>Unfold</Text>
        </Pressable>
        <Pressable accessibilityRole="button" accessibilityState={{ disabled: target >= STEP_COUNT }} onPress={() => setTarget((t) => Math.min(STEP_COUNT, t + 1))} style={chip(false)}>
          <Text style={{ fontSize: 12, color: "#315843", fontFamily: "Geist-Regular" }}>Fold</Text>
        </Pressable>
        <Pressable accessibilityRole="switch" accessibilityState={{ checked: slow }} onPress={() => setSlow((v) => !v)} style={chip(slow)}>
          <Text style={{ fontSize: 12, color: slow ? "#fff" : "#315843", fontFamily: "Geist-Regular" }}>Slow motion: {slow ? "on" : "off"}</Text>
        </Pressable>
        <Pressable accessibilityRole="switch" accessibilityState={{ checked: reduce }} onPress={() => setReduce((v) => !v)} style={chip(reduce)}>
          <Text style={{ fontSize: 12, color: reduce ? "#fff" : "#315843", fontFamily: "Geist-Regular" }}>Reduce motion: {reduce ? "on" : "off"}</Text>
        </Pressable>
      </View>
    </View>
  );
}
